import json
from collections import defaultdict

BASE = '/root/provenance_weight_training/output/models'
TAU = 0.7

def classify_regime(b, alpha_eff, tau):
    if b == 0.0:
        return 'clean'
    if alpha_eff >= tau - 0.005:
        return 'alpha_eff_binding'
    return 'ess_binding'

def find_run_boundaries(data):
    boundaries = [0]
    for i in range(1, len(data)):
        if data[i]['step'] < data[i-1]['step']:
            boundaries.append(i)
    return boundaries

def load_deduped(path):
    with open(path) as f:
        data = [json.loads(line) for line in f]
    if len(data) == 0:
        return []
    boundaries = find_run_boundaries(data)
    if len(boundaries) == 1:
        step_entries = defaultdict(list)
        for d in data:
            step_entries[d['step']].append(d)
        result = []
        for step in sorted(step_entries.keys()):
            result.extend(step_entries[step][:4])
        return result
    run0_end = boundaries[1]
    final_run_start = boundaries[-1]
    restart_step = data[final_run_start]['step']
    initial = defaultdict(list)
    for d in data[:run0_end]:
        if d['step'] < restart_step:
            initial[d['step']].append(d)
    final = defaultdict(list)
    for d in data[final_run_start:]:
        final[d['step']].append(d)
    result = []
    for step in sorted(initial.keys()):
        result.extend(initial[step][:4])
    for step in sorted(final.keys()):
        result.extend(final[step][:4])
    return result

seeds = {'tau07_seed42': 42, 'tau07_seed123': 123, 'tau07_seed456': 456}
all_stats = {}
combined_counts = defaultdict(int)
combined_total = 0

for exp, seed in seeds.items():
    path = f'{BASE}/{exp}/step_metrics.jsonl'
    raw = load_deduped(path)
    counts = defaultdict(int)
    for d in raw:
        regime = classify_regime(d['b'], d['alpha_eff'], TAU)
        counts[regime] += 1
    total = len(raw)
    pcts = {k: round(100 * v / total, 2) for k, v in sorted(counts.items())}
    all_stats[exp] = {'total': total, 'counts': dict(counts), 'pcts': pcts}
    for k, v in counts.items():
        combined_counts[k] += v
    combined_total += total
    print(f'{exp}: total={total}, pcts={pcts}')

print()
print('=== 3-seed average ===')
avg_pcts = {k: round(100 * v / combined_total, 2) for k, v in sorted(combined_counts.items())}
print(f'Combined: total={combined_total}, pcts={avg_pcts}')
